package example
import "context"
// 等待取消或 deadline 到期，保留具体错误。
func WaitForCancel(ctx context.Context) error { <-ctx.Done(); return ctx.Err() }

// fixture version 2

package example
import ("context"; "errors"; "testing"; "time")
func TestServerAlreadyCancelled(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());cancel()
    if !errors.Is(WaitForCancel(ctx),context.Canceled) {t.Fatal("必须返回取消错误")}
}
func TestServerWaitsThenCancels(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());defer cancel()
    done:=make(chan error,1);go func(){done<-WaitForCancel(ctx)}()
    select {case <-done:t.Fatal("取消前不能提前返回");case <-time.After(20*time.Millisecond):}
    cancel()
    select {case err:=<-done:if !errors.Is(err,context.Canceled){t.Fatal(err)};case <-time.After(time.Second):t.Fatal("未响应取消")}
}
func TestServerDeadline(t *testing.T) {
    ctx,cancel:=context.WithTimeout(context.Background(),20*time.Millisecond);defer cancel()
    if !errors.Is(WaitForCancel(ctx),context.DeadlineExceeded){t.Fatal("必须传播超时")}
}

package example
import ("context";"testing";"time")
func TestEvalContextIdentity(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());cancel()
    if WaitForCancel(ctx)!=ctx.Err(){t.Fatal("must return exact ctx.Err, not only errors.Is")}
    deadline,stop:=context.WithTimeout(context.Background(),time.Millisecond);defer stop()
    if WaitForCancel(deadline)!=context.DeadlineExceeded{t.Fatal("deadline identity")}
}
func TestEvalContextWait(t *testing.T) {
    ctx,cancel:=context.WithCancel(context.Background());defer cancel()
    done:=make(chan error,1);go func(){done<-WaitForCancel(ctx)}()
    select {case <-done:t.Fatal("returned before cancellation");case <-time.After(12*time.Millisecond):}
    cancel();select {case err:=<-done:if err!=context.Canceled{t.Fatal(err)};case <-time.After(time.Second):t.Fatal("cancel ignored")}
}

